<script setup>
import PaperProgress from './PaperProgress.vue';
import {ref,onMounted} from 'vue';import {api,session,go} from './api';import {answerText,clock} from './utils';import MathText from './MathText.vue';import QuestionContent from './QuestionContent.vue';import AnswerValue from './AnswerValue.vue';
const props=defineProps({route:String});const items=ref([]),total=ref(0),page=ref(1),error=ref(''),dashboard=ref(null),attempt=ref(null),showReview=ref(false),review=ref([]),reviewTotal=ref(0),reviewPage=ref(1);
const result=props.route.startsWith('/result/'),collection=props.route==='/bookmarks';const active=ref([]);
async function load(){try{
 if(result){attempt.value=await api('/attempts/'+props.route.split('/')[2]);if(attempt.value.status==='ACTIVE')go('/attempt/'+attempt.value.id)}
 else if(collection){const d=await api('/bookmarks?page='+page.value);items.value=d.items;total.value=d.total}
 else{const d=await api('/progress?page='+page.value);items.value=d.items;total.value=d.total;active.value=(await api('/attempts?limit=100')).items}
}catch(e){error.value=e.message}}
onMounted(load);
async function practice(paper_id){try{const a=await api('/attempts',{method:'POST',body:collection?{collection:props.route.slice(1),mode:'practice'}:{paper_id,mode:'practice'}});go('/attempt/'+a.id)}catch(e){error.value=e.message}}
async function practiceWrong(){try{const a=await api('/attempts',{method:'POST',body:{collection:'mistakes',attempt_id:attempt.value.id,mode:'practice'}});go('/attempt/'+a.id)}catch(e){error.value=e.message}}
async function getReview(){try{const d=await api('/attempts/'+attempt.value.id+'/review?page='+reviewPage.value);review.value=d.items;reviewTotal.value=d.total;showReview.value=true}catch(e){error.value=e.message}}
async function remove(id){await api('/questions/'+id+'/bookmark',{method:'DELETE'});await load()}
</script>
<template><div v-if="error" class="alert alert-danger">{{error}}</div>
<template v-if="result&&attempt"><div class="eyebrow">ATTEMPT COMPLETE</div><h1>Your results</h1><p class="muted">{{attempt.title}}</p><p class="notice">Results and question review are temporary, available until {{new Date(attempt.expires_at*1000).toLocaleString()}}. Only your latest paper percentage is saved in this browser.</p><p v-if="attempt.records_progress===false" class="muted">This targeted practice does not replace your full-paper score.</p><div class="result-panel panel" v-if="attempt.result"><div class="result-score"><span class="eyebrow">{{attempt.result.pending_manual?'PROVISIONAL SCORE':'YOUR SCORE'}}</span><strong>{{attempt.result.score}}<small> / {{attempt.result.total_marks??'—'}}</small></strong><span>{{attempt.result.percentage===null?'Percentage unavailable':attempt.result.percentage+'%'}}</span></div><div class="result-grid"><div v-for="k in ['correct','incorrect','skipped','attempted','ungraded','accuracy']"><strong>{{attempt.result[k]??'—'}}{{k==='accuracy'&&attempt.result[k]!==null?'%':''}}</strong><span>{{k}}</span></div></div></div><p v-if="attempt.result?.pending_manual" class="alert alert-warning">Some responses have no reliable source key/marks or cannot be automatically graded. The score is provisional.</p><p class="muted">Time taken: {{clock(attempt.result?.time_taken||0)}} · Negative marks: {{attempt.result?.negative_marks}}</p><div class="d-flex gap-3 flex-wrap"><button class="btn btn-primary" @click="getReview">Review solutions</button><button v-if="attempt.result?.incorrect>0" class="btn btn-outline-primary" @click="practiceWrong">Practice wrong answers ({{attempt.result.incorrect}})</button><button v-if="attempt.paper_id" class="btn btn-outline-primary" @click="practice(attempt.paper_id)">Practice again</button><a class="btn btn-light" :href="attempt.paper_id?'#/paper/'+attempt.paper_id:'#/progress'">Back to {{attempt.paper_id?'paper':'progress'}}</a></div><section v-if="showReview" class="mt-4"><article v-for="i in review" class="panel review-card" :class="'review-'+String(i.outcome||'UNGRADED').toLowerCase()"><div class="section-row"><h3>Question {{i.question.number}}</h3><span class="status review-outcome">{{i.outcome==='CORRECT'?'Correct':i.outcome==='INCORRECT'?'Incorrect':i.outcome==='SKIPPED'?'Not attempted':'Ungraded'}} · {{i.awarded??'—'}} marks</span></div><QuestionContent :text="i.question.text" :images="(i.question.images||[]).filter(x=>!x.option_key)"/><div v-for="o in i.question.options" class="review-option"><strong>{{String.fromCharCode(65+i.question.options.indexOf(o))}}.</strong><QuestionContent :text="o.text" :images="(i.question.images||[]).filter(x=>x.option_key===o.key)"/></div><div class="answer-comparison"><div><span>Your answer</span><AnswerValue :question="i.question" :value="i.answer" empty="Not answered"/></div><div><span>Correct answer</span><AnswerValue :question="i.question" :value="i.question.answers"/></div></div><MathText :text="i.question.explanation||'Solution explanation not available.'"/><p v-if="i.manual_note">Reviewer: {{i.manual_note}}</p></article><div class="pagination-row" v-if="reviewTotal>24"><button class="btn btn-light" :disabled="reviewPage===1" @click="reviewPage--;getReview()">Previous</button><span>{{reviewPage}}</span><button class="btn btn-light" :disabled="reviewPage*24>=reviewTotal" @click="reviewPage++;getReview()">Next</button></div></section></template>
<section v-else-if="result" class="empty panel"><p v-if="!error">Loading result…</p><p v-else>Open My progress to see your latest paper score or retake a paper.</p><a class="btn btn-primary" href="#/progress">My progress</a></section>
<template v-else>
<div class="eyebrow">YOUR PRACTICE WORKSPACE</div>
<div class="section-row"><h1>{{collection?'My bookmarks':'My progress'}}</h1><button v-if="collection&&items.length" class="btn btn-primary" @click="practice()">Practice bookmarks</button></div>
<p v-if="!collection" class="muted">One latest score per paper. Retaking a paper replaces its previous score; scores and bookmarks stay on this browser only. Clearing site data removes them.</p>
<section v-if="!collection&&active.length" class="panel mb-4"><h2>Continue an active session</h2><div v-for="a in active" :key="a.id" class="section-row"><span>{{a.title}} · {{a.mode}}</span><a class="btn btn-light" :href="'#/attempt/'+a.id">Resume</a></div></section>
<div v-if="!items.length" class="empty panel"><h3>{{collection?'No bookmarks yet.':'No completed papers yet.'}}</h3><a href="#/" class="btn btn-primary">Explore courses</a></div>
<template v-else-if="collection"><article class="panel review-card" v-for="q in items" :key="q.id"><span class="eyebrow">{{q.kind}} · {{q.topic||'Topic not specified'}}</span><QuestionContent :text="q.text" :images="(q.images||[]).filter(x=>!x.option_key)"/><div class="d-flex gap-2 mt-3"><a :href="'#/paper/'+q.paper_id" class="btn btn-light">Open paper</a><button class="text-btn" @click="remove(q.id)">Remove bookmark</button></div></article></template>
<template v-else><article v-for="p in items" :key="p.paper_id" class="paper-row panel"><div class="paper-info"><span class="eyebrow">{{p.course}} · {{p.exam}} · {{p.term}}</span><h3>{{p.name}}</h3><PaperProgress :progress="p"/></div><a class="btn btn-primary" :href="'#/paper/'+p.paper_id">Retake Test</a></article></template>
<div v-if="total>24" class="pagination-row"><button class="btn btn-light" :disabled="page===1" @click="page--;load()">Previous</button><span>Page {{page}}</span><button class="btn btn-light" :disabled="page*24>=total" @click="page++;load()">Next</button></div>
</template></template>
